"use client";

import Link from "next/link";
import { useState } from "react";
import { CategoryNode } from "@/types/blog";

interface CategoryTreeProps {
  nodes: CategoryNode[];
  activeSlug?: string;
}

export default function CategoryTree({ nodes, activeSlug }: CategoryTreeProps) {
  return (
    <ul className="category-tree">
      {nodes.map((node) => (
        <CategoryTreeItem key={node.id} node={node} activeSlug={activeSlug} />
      ))}
    </ul>
  );
}

function CategoryTreeItem({
  node,
  activeSlug,
}: {
  node: CategoryNode;
  activeSlug?: string;
}) {
  const [expanded, setExpanded] = useState(true);
  const hasChildren = node.children.length > 0;

  return (
    <li className="category-item">
      <div className="category-row">
        <button
          type="button"
          className={hasChildren ? "category-toggle" : "category-toggle category-toggle--leaf"}
          onClick={() => hasChildren && setExpanded((prev) => !prev)}
          disabled={!hasChildren}
          aria-label={hasChildren ? (expanded ? "접기" : "펼치기") : undefined}
        >
          {hasChildren ? (expanded ? "▾" : "▸") : "·"}
        </button>
        <Link
          href={`/?category=${node.slug}`}
          className={
            node.slug === activeSlug
              ? "category-link category-link--active"
              : "category-link"
          }
        >
          <span>{node.name}</span>
          <span className="category-count">{node.postCount}</span>
        </Link>
      </div>
      {hasChildren && expanded ? (
        <ul className="category-tree">
          {node.children.map((child) => (
            <CategoryTreeItem key={child.id} node={child} activeSlug={activeSlug} />
          ))}
        </ul>
      ) : null}
    </li>
  );
}
